{
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "dev": "node server.js",
    "build": "echo \"no build step configured\""
  },
  "devDependencies": {
    "vitest": "^3.1.3"
  }
}

import { createServer } from "node:http";
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { randomUUID } from "node:crypto";

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_PATH = join(__dirname, "data", "books.json");
const PORT = Number(process.env.PORT) || 3000;

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

async function loadBooks() {
  try {
    const raw = await readFile(DATA_PATH, "utf8");
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (err) {
    if (err && err.code === "ENOENT") return [];
    throw err;
  }
}

async function saveBooks(books) {
  await mkdir(dirname(DATA_PATH), { recursive: true });
  await writeFile(DATA_PATH, JSON.stringify(books, null, 2) + "\n", "utf8");
}

function page(title, body) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <style>
    :root { color-scheme: light; }
    body { font-family: Georgia, serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #1c1917; background: #faf7f2; }
    h1, h2 { font-weight: normal; }
    a { color: #7c2d12; }
    form, .card { background: #fff; border: 1px solid #e7e5e4; padding: 1rem; margin: 1rem 0; }
    label { display: block; margin-top: 0.75rem; font-size: 0.9rem; }
    input, textarea { width: 100%; box-sizing: border-box; font: inherit; padding: 0.4rem; margin-top: 0.25rem; }
    button, .button { font: inherit; background: #7c2d12; color: #fff; border: 0; padding: 0.4rem 0.8rem; cursor: pointer; text-decoration: none; display: inline-block; }
    button.secondary { background: #44403c; }
    ul { list-style: none; padding: 0; }
    li { margin: 0.4rem 0; }
    .empty { color: #78716c; font-style: italic; }
    .meta { color: #57534e; }
    nav { margin-bottom: 1rem; }
  </style>
</head>
<body>
  <nav><a href="/">Books</a></nav>
  ${body}
</body>
</html>`;
}

function bookList(books) {
  if (books.length === 0) return `<p class="empty">None yet.</p>`;
  return `<ul>${books
    .map(
      (book) =>
        `<li><a href="/books/${escapeHtml(book.id)}">${escapeHtml(book.title)}</a> <span class="meta">by ${escapeHtml(book.author)}</span></li>`
    )
    .join("")}</ul>`;
}

function homePage(books) {
  const reading = books.filter((book) => book.status !== "finished");
  const finished = books.filter((book) => book.status === "finished");
  const body = `
    <h1>Reading list</h1>
    <h2>Currently reading</h2>
    ${bookList(reading)}
    <h2>Finished</h2>
    ${bookList(finished)}
    <h2>Add a book</h2>
    <form method="post" action="/books">
      <label>Title <input name="title" required></label>
      <label>Author <input name="author" required></label>
      <label>Notes <textarea name="notes" rows="4"></textarea></label>
      <p><button type="submit">Add book</button></p>
    </form>`;
  return page("Reading list", body);
}

function bookPage(book) {
  const finished = book.status === "finished";
  const body = `
    <h1>${escapeHtml(book.title)}</h1>
    <p class="meta">by ${escapeHtml(book.author)}</p>
    <p>${finished ? "Finished" : "Currently reading"}</p>
    <h2>Notes</h2>
    <p>${book.notes ? escapeHtml(book.notes).replaceAll("\n", "<br>") : `<span class="empty">No notes yet.</span>`}</p>
    ${
      finished
        ? ""
        : `<form method="post" action="/books/${escapeHtml(book.id)}/finish">
             <button type="submit">Mark as finished</button>
           </form>`
    }
    <p class="meta">Share this page: <a href="/books/${escapeHtml(book.id)}">/books/${escapeHtml(book.id)}</a></p>`;
  return page(book.title, body);
}

function parseForm(raw) {
  const params = new URLSearchParams(raw);
  return {
    title: (params.get("title") || "").trim(),
    author: (params.get("author") || "").trim(),
    notes: (params.get("notes") || "").trim(),
  };
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on("data", (chunk) => chunks.push(chunk));
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", reject);
  });
}

function send(res, status, html) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url || "/", `http://${req.headers.host || "localhost"}`);
  const path = url.pathname;
  const method = req.method || "GET";

  try {
    if (method === "GET" && path === "/") {
      send(res, 200, homePage(await loadBooks()));
      return;
    }

    if (method === "POST" && path === "/books") {
      const form = parseForm(await readBody(req));
      if (!form.title || !form.author) {
        send(res, 400, page("Missing fields", `<p>Title and author are required.</p><p><a href="/">Back</a></p>`));
        return;
      }
      const books = await loadBooks();
      const book = {
        id: randomUUID(),
        title: form.title,
        author: form.author,
        notes: form.notes,
        status: "reading",
      };
      books.push(book);
      await saveBooks(books);
      redirect(res, `/books/${book.id}`);
      return;
    }

    const bookMatch = path.match(/^\/books\/([^/]+)$/);
    if (method === "GET" && bookMatch) {
      const books = await loadBooks();
      const book = books.find((item) => item.id === bookMatch[1]);
      if (!book) {
        send(res, 404, page("Not found", `<p>That book isn't on the list.</p>`));
        return;
      }
      send(res, 200, bookPage(book));
      return;
    }

    const finishMatch = path.match(/^\/books\/([^/]+)\/finish$/);
    if (method === "POST" && finishMatch) {
      const books = await loadBooks();
      const book = books.find((item) => item.id === finishMatch[1]);
      if (!book) {
        send(res, 404, page("Not found", `<p>That book isn't on the list.</p>`));
        return;
      }
      book.status = "finished";
      await saveBooks(books);
      redirect(res, `/books/${book.id}`);
      return;
    }

    send(res, 404, page("Not found", `<p>Page not found.</p>`));
  } catch (err) {
    send(res, 500, page("Error", `<p>Something went wrong.</p>`));
    console.error(err);
  }
});

server.listen(PORT, () => {
  console.log(`Reading list at http://localhost:${PORT}`);
});

